export const BlivapLogo = ({
  fill = "white",
  width,
  height,
  className,
  animate = true,
}: SvgProps) => {
  const uid = useId();
  const filterId = `blivap-glow-${uid.replace(/:/g, "")}`;
  const containerRef = useRef<HTMLSpanElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const motionRef = useRef<SVGGElement>(null);

  useEffect(() => {
    if (
      !animate ||
      !svgRef.current ||
      !motionRef.current ||
      !containerRef.current
    )
      return;

    const svg = svgRef.current;
    const motion = motionRef.current;
    const pathEl = motion.querySelector(".blivap-drop-fill");
    const blur = svg.querySelector(
      `#${CSS.escape(filterId)} feGaussianBlur`,
    ) as SVGFEGaussianBlurElement | null;

    const ctx = gsap.context(() => {
      gsap.set(motion, {
        transformOrigin: "50% 58%",
        willChange: "transform",
      });

      const intro = gsap.timeline();

      intro.from(motion, {
        scale: 0,
        rotation: -22,
        opacity: 0,
        duration: 1.2,
        ease: "back.out(2.15)",
      });

      if (pathEl) {
        intro.fromTo(
          pathEl,
          { opacity: 0.55 },
          { opacity: 1, duration: 0.55, ease: "power2.out" },
          "-=0.85",
        );
      }

      intro.add(() => {
        gsap.to(svg, {
          y: -6,
          duration: 2.75,
          ease: "sine.inOut",
          repeat: -1,
          yoyo: true,
        });

        gsap.timeline({ repeat: -1, repeatDelay: 1.6 }).to(motion, {
          keyframes: [
            { scale: 1, duration: 0 },
            { scale: 1.09, duration: 0.18, ease: "power2.out" },
            { scale: 1, duration: 0.45, ease: "elastic.out(1.12)" },
          ],
        });

        gsap.to(motion, {
          rotation: 5,
          duration: 4.5,
          ease: "sine.inOut",
          repeat: -1,
          yoyo: true,
        });

        if (blur) {
          gsap.fromTo(
            blur,
            { attr: { stdDeviation: 0 } },
            {
              attr: { stdDeviation: 4.5 },
              duration: 2.1,
              ease: "sine.inOut",
              repeat: -1,
              yoyo: true,
            },
          );
        }
      });
    }, containerRef);

    return () => ctx.revert();
  }, [animate, filterId]);

  return (
    <span
      ref={containerRef}
      className={cn(
        "inline-flex shrink-0 items-center justify-center overflow-visible",
        className,
      )}
      style={
        width !== undefined || height !== undefined
          ? {
              width: width ?? height,
              height: height ?? width,
            }
          : undefined
      }
    >
      <svg
        ref={svgRef}
        viewBox="0 0 53 113"
        xmlns="http://www.w3.org/2000/svg"
        className="h-full max-h-full w-auto"
        preserveAspectRatio="xMidYMid meet"
        aria-hidden
      >
        <defs>
          <filter
            id={filterId}
            x="-50%"
            y="-40%"
            width="200%"
            height="200%"
            colorInterpolationFilters="sRGB"
          >
            <feGaussianBlur in="SourceGraphic" stdDeviation="0" result="b" />
            <feMerge>
              <feMergeNode in="b" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <g ref={motionRef} filter={`url(#${filterId})`}>
          <path className="blivap-drop-fill" d={DROP_PATH} fill={fill} />
        </g>
      </svg>
    </span>
  );
};
